package com.csust.eyediagnosis.workflow.persistence;

import org.flywaydb.core.Flyway;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import java.sql.*;
import static org.junit.jupiter.api.Assertions.*;

class WorkflowPersistenceConstraintsTest {
    private JdbcDataSource ds;
    @BeforeEach void migrate() throws Exception { ds=new JdbcDataSource(); ds.setURL("jdbc:h2:mem:constraints"+System.nanoTime()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1"); ds.setUser("sa"); try(Connection c=ds.getConnection();Statement s=c.createStatement()){s.execute("create table anchor(id int primary key)");} Flyway.configure().dataSource(ds).baselineOnMigrate(true).baselineVersion("9").locations("classpath:db/migration").load().migrate(); }
    @Test void businessUniqueConstraintsAndCasProtectWorkflowData() throws Exception { try(Connection c=ds.getConnection(); Statement s=c.createStatement()) {
        s.execute("insert into t_diagnosis_workflow(workflowId,ownerUserId,creationIdempotencyKey,status,graphDefinitionVersion,graphDefinitionHash,actionVersion,explanationPublicationStatus,predictionExposureStatus) values('w',1,'k','CREATED','v','h','a','NONE','NOT_AVAILABLE')");
        assertThrows(SQLException.class,()->s.execute("insert into t_diagnosis_workflow(workflowId,ownerUserId,creationIdempotencyKey,status,graphDefinitionVersion,graphDefinitionHash,actionVersion,explanationPublicationStatus,predictionExposureStatus) values('w2',1,'k','CREATED','v','h','a','NONE','NOT_AVAILABLE')"));
        assertEquals(1,s.executeUpdate("update t_diagnosis_workflow set status='QUEUED', workflowVersion=workflowVersion+1 where workflowId='w' and workflowVersion=0 and status='CREATED'")); assertEquals(0,s.executeUpdate("update t_diagnosis_workflow set status='RUNNING', workflowVersion=workflowVersion+1 where workflowId='w' and workflowVersion=0"));
        s.execute("insert into t_diagnosis_workflow_event(eventId,workflowId,eventSequence,eventType,actorType,workflowVersion) values('e','w',1,'X','SYSTEM',0)"); assertThrows(SQLException.class,()->s.execute("insert into t_diagnosis_workflow_event(eventId,workflowId,eventSequence,eventType,actorType,workflowVersion) values('e2','w',1,'X','SYSTEM',0)"));
        s.execute("insert into t_workflow_job(jobId,workflowId,jobType,segmentCode,executionEpoch,status,maxAttempts) values('j','w','START_SEGMENT','INTAKE_INFERENCE_QUALITY',0,'READY',1)"); assertThrows(SQLException.class,()->s.execute("insert into t_workflow_job(jobId,workflowId,jobType,segmentCode,executionEpoch,status,maxAttempts) values('j2','w','START_SEGMENT','INTAKE_INFERENCE_QUALITY',0,'READY',1)"));
        s.execute("insert into t_workflow_node_execution(nodeExecutionId,workflowId,executionEpoch,segmentCode,nodeCode,idempotencyKey,status) values('n','w',0,'INTAKE_INFERENCE_QUALITY','N','i','DONE')"); assertThrows(SQLException.class,()->s.execute("insert into t_workflow_node_execution(nodeExecutionId,workflowId,executionEpoch,segmentCode,nodeCode,idempotencyKey,status) values('n2','w',0,'INTAKE_INFERENCE_QUALITY','N','i','DONE')"));
        s.execute("insert into t_inference_envelope(inferenceEnvelopeId,workflowId,inferenceEpoch,imageObjectReference,inputDigest,qualityOutcome,qualityScore,inferenceOutcomeType,modelVersion,modelWeightFingerprint,inferredAt) values('i1','w',0,'object','digest','PASS',100,'VALID_PREDICTION','m','f',CURRENT_TIMESTAMP)"); assertThrows(SQLException.class,()->s.execute("insert into t_inference_envelope(inferenceEnvelopeId,workflowId,inferenceEpoch,imageObjectReference,inputDigest,qualityOutcome,qualityScore,inferenceOutcomeType,modelVersion,modelWeightFingerprint,inferredAt) values('i2','w',0,'object','digest','PASS',100,'VALID_PREDICTION','m','f',CURRENT_TIMESTAMP)"));
        s.execute("insert into t_diagnosis_citation(citationId,workflowId,retrievalEpoch,sourceDocumentId,sourceRevision,visibilitySnapshot,reviewStatusSnapshot,quotedSpan,quotedSpanDigest,retrievedAt) values('c1','w',0,'d','r','VISIBLE','ACCEPTED','quote','q',CURRENT_TIMESTAMP)"); assertThrows(SQLException.class,()->s.execute("insert into t_diagnosis_citation(citationId,workflowId,retrievalEpoch,sourceDocumentId,sourceRevision,visibilitySnapshot,reviewStatusSnapshot,quotedSpan,quotedSpanDigest,retrievedAt) values('c2','w',0,'d','r','VISIBLE','ACCEPTED','quote','q',CURRENT_TIMESTAMP)"));
        s.execute("insert into t_explanation_snapshot(explanationSnapshotId,workflowId,revision,publicationStatus,contentSnapshot) values('x1','w',1,'DRAFT','content')"); assertThrows(SQLException.class,()->s.execute("insert into t_explanation_snapshot(explanationSnapshotId,workflowId,revision,publicationStatus,contentSnapshot) values('x2','w',1,'DRAFT','content')"));
        s.execute("insert into t_human_review_task(reviewTaskId,workflowId,reviewType,reviewRound,status) values('r','w','IMAGE_QUALITY_GATE',1,'OPEN')"); assertEquals(1,s.executeUpdate("update t_human_review_task set status='CLAIMED',taskVersion=taskVersion+1 where reviewTaskId='r' and taskVersion=0")); assertEquals(0,s.executeUpdate("update t_human_review_task set status='DONE',taskVersion=taskVersion+1 where reviewTaskId='r' and taskVersion=0"));
        assertThrows(SQLException.class,()->s.execute("insert into t_human_review_task(reviewTaskId,workflowId,reviewType,reviewRound,status) values('r2','w','IMAGE_QUALITY_GATE',1,'OPEN')"));
    }}
}
